const KEY_EVO = 'f7aaaba7593506765800c7d58133007a';
const INSTANCE = 'secretaria-clinica';
const TG_TOKEN = '8934272933:AAGq-Gfro0Ia-KiK8dEc3MK8YCPuORqC40Y';
const TG_CHAT = '5711916728';
const QR_URL = 'https://<REDACTED_PRIVATE_HOST>/webhook/secretaria-qr';
const https = require('https');

function getState(){
  return new Promise((resolve)=>{
    const req = https.request({ hostname:\<REDACTED_PRIVATE_HOST>', path:'/instance/connectionState/'+INSTANCE, method:'GET', headers:{ 'apikey':KEY_EVO } }, (res)=>{ let d=''; res.on('data',c=>d+=c); res.on('end',()=>{ try{ const j=JSON.parse(d); resolve((j.instance && j.instance.state) || 'unknown'); }catch(e){ resolve('parse-error'); } }); });
    req.on('error',()=>resolve('req-error'));
    req.setTimeout(15000,()=>{ req.destroy(); resolve('timeout'); });
    req.end();
  });
}

function restart(){
  return new Promise((resolve)=>{
    const req = https.request({ hostname:\<REDACTED_PRIVATE_HOST>', path:'/instance/restart/'+INSTANCE, method:'POST', headers:{ 'apikey':KEY_EVO } }, (res)=>{ let d=''; res.on('data',c=>d+=c); res.on('end',()=>resolve(res.statusCode)); });
    req.on('error',()=>resolve(0));
    req.setTimeout(15000,()=>{ req.destroy(); resolve(0); });
    req.end();
  });
}

function tg(text){
  return new Promise((resolve)=>{
    const payload = JSON.stringify({ chat_id: TG_CHAT, text: text, disable_web_page_preview: true });
    const req = https.request({ hostname:'api.telegram.org', path:'/bot'+TG_TOKEN+'/sendMessage', method:'POST', headers:{ 'Content-Type':'application/json', 'Content-Length':Buffer.byteLength(payload) } }, (res)=>{ let d=''; res.on('data',c=>d+=c); res.on('end',()=>resolve(res.statusCode)); });
    req.on('error',()=>resolve(0));
    req.setTimeout(15000,()=>{ req.destroy(); resolve(0); });
    req.write(payload); req.end();
  });
}

const s = $getWorkflowStaticData('global');
const st = await getState();
const up = (st === 'open');
let action = 'none';

if (up) {
  s.downCount = 0;
  if (s.downAlerted) {
    const mins = s.downSince ? Math.round((Date.now() - s.downSince)/60000) : 0;
    await tg('🟢 SECRETARIA IA VOLTOU\n\nInstancia reconectada. Ficou fora ~' + mins + ' min. Atendimento normal.');
    s.downAlerted = false; s.qrSent = false; action = 'recovered';
  }
} else {
  s.downCount = (s.downCount || 0) + 1;
  if (s.downCount === 2) {
    const rc = await restart();
    s.downAlerted = true; s.downSince = s.downSince || Date.now();
    await tg('🔴 SECRETARIA IA CAIU (estado: ' + st + ').\n\nTentando reconectar sozinho (restart ' + rc + ')... Se nao voltar, te mando o QR no proximo aviso.');
    action = 'restart-try';
  } else if (s.downCount >= 3 && !s.qrSent) {
    await tg('🔴 NAO reconectou sozinho.\n\nReligue escaneando o QR aqui:\n' + QR_URL + '\n\nNo celular do numero: WhatsApp > Aparelhos conectados > Conectar um aparelho. A pagina atualiza o QR sozinha.');
    s.qrSent = true; action = 'qr-sent';
  }
}

return [{ json:{ state: st, up, downCount: s.downCount || 0, alerted: s.downAlerted || false, action, at: new Date().toISOString() } }];

